import{_t as e,it as t,n,rt as r}from"./chunks/framework.BhEEDjPG.js";var i=JSON.parse(`{"title":"Production-readiness checklist","description":"","frontmatter":{},"headers":[],"relativePath":"run/production-checklist.md","filePath":"run/production-checklist.md"}`),a={name:`run/production-checklist.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="production-readiness-checklist" tabindex="-1">Production-readiness checklist <a class="header-anchor" href="#production-readiness-checklist" aria-label="Permalink to “Production-readiness checklist”">​</a></h1><p>Every item here was a real blocker or incident in the first production vertical (an audit found eight blockers; the hardening that followed produced this list). Walk it before any deploy; walk §1–3 at design time.</p><h2 id="_1-identity-session-security" tabindex="-1">1. Identity &amp; session security <a class="header-anchor" href="#_1-identity-session-security" aria-label="Permalink to “1. Identity &amp; session security”">​</a></h2><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-0" disabled="disabled"><label class="task-list-item-label" for="task-item-0"> Login required (<code>AGENT_REQUIRE_LOGIN</code> unset = on). Dev convenience never becomes identity.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-1" disabled="disabled"><label class="task-list-item-label" for="task-item-1"> Identity VERIFIED against your auth service (<code>AGENT_AUTH_VERIFY_URL</code>), cached 60 s, failing closed (401 on rejection, 503 when unreachable). A bare JWT decode scopes listings in dev only.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-2" disabled="disabled"><label class="task-list-item-label" for="task-item-2"> A session id is never a credential: every session route checks the owner and answers 404 on a mismatch.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-3" disabled="disabled"><label class="task-list-item-label" for="task-item-3"> Admin routes (<code>/api/sessions</code>, <code>/api/metrics</code>, <code>/api/usage</code>, <code>/api/system-prompt</code>, <code>/api/decide</code>) require <code>AGENT_ADMIN_KEY</code> and are DISABLED when none is set in a keyed/login deployment.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-4" disabled="disabled"><label class="task-list-item-label" for="task-item-4"> The user&#39;s token rides MCP <code>_meta</code>, never model-visible arguments; never persisted; re-supplied per turn. An agent-token exchange keeps the broad upstream token out of web views (docs/SDK-AUTH.md).</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-5" disabled="disabled"><label class="task-list-item-label" for="task-item-5"> Tokens, keys, passwords, OTPs and private notes never appear in logs (<code>redact()</code>), spans or ledgers.</label></li></ul><h2 id="_2-write-path-integrity" tabindex="-1">2. Write-path integrity <a class="header-anchor" href="#_2-write-path-integrity" aria-label="Permalink to “2. Write-path integrity”">​</a></h2><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-6" disabled="disabled"><label class="task-list-item-label" for="task-item-6"> The confirm gate ×3: skill rule, tool schema (<code>confirmed:true</code> + <code>AGENT_ALLOW_WRITES === &quot;true&quot;</code>), runtime guard (summary shown for this draft + whole-content yes).</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-7" disabled="disabled"><label class="task-list-item-label" for="task-item-7"> The backend was PROBED: real mandatories, schema warts, which base URLs share a database, whether a GET writes. Findings live in the schema registry.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-8" disabled="disabled"><label class="task-list-item-label" for="task-item-8"> Timeout + idempotency on the write (key = session + draft fingerprint; reconcile before retrying).</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-9" disabled="disabled"><label class="task-list-item-label" for="task-item-9"> No silent fuzzy fallback on the write path; the write uses only ids the user confirmed.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-10" disabled="disabled"><label class="task-list-item-label" for="task-item-10"> Links are tool-composed or templated (<code>AGENT_ENTITY_DEEPLINK</code>), never model-invented; the scheme allowlist is on (<code>AGENT_LINK_SCHEMES</code> for your app&#39;s scheme).</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-11" disabled="disabled"><label class="task-list-item-label" for="task-item-11"> Attested lists configured for anything published under the user&#39;s name (<code>attested_lists</code>).</label></li></ul><h2 id="_3-client-security" tabindex="-1">3. Client security <a class="header-anchor" href="#_3-client-security" aria-label="Permalink to “3. Client security”">​</a></h2><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-12" disabled="disabled"><label class="task-list-item-label" for="task-item-12"> CORS allowlist (<code>AGENT_CORS_ORIGINS</code>), gateway keys (<code>AGENT_GATEWAY_KEYS</code>), message cap (<code>AGENT_MAX_MESSAGE_CHARS</code>), security headers (always on).</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-13" disabled="disabled"><label class="task-list-item-label" for="task-item-13"> History replay carries user/assistant prose + blocks only; tool payloads never leave the server.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-14" disabled="disabled"><label class="task-list-item-label" for="task-item-14"> The injection preamble is in every prompt; an injection scenario is in every suite.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-15" disabled="disabled"><label class="task-list-item-label" for="task-item-15"> The widget script URL is pinned to its version behind any caching proxy.</label></li></ul><h2 id="_4-lifecycle-resilience" tabindex="-1">4. Lifecycle &amp; resilience <a class="header-anchor" href="#_4-lifecycle-resilience" aria-label="Permalink to “4. Lifecycle &amp; resilience”">​</a></h2><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-16" disabled="disabled"><label class="task-list-item-label" for="task-item-16"> SIGTERM drains in-flight turns (bounded), closes MCP children, flushes logs and telemetry.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-17" disabled="disabled"><label class="task-list-item-label" for="task-item-17"> MCP children reconnect on a transport failure (built in); <code>/api/health</code> shows reconnect counts.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-18" disabled="disabled"><label class="task-list-item-label" for="task-item-18"> Sessions hydrate lazily and evict (<code>AGENT_SESSION_CACHE</code>); nothing loads everything at boot.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-19" disabled="disabled"><label class="task-list-item-label" for="task-item-19"> History windows on turn boundaries and heals tool pairs (built in).</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-20" disabled="disabled"><label class="task-list-item-label" for="task-item-20"> Degradation paths are typed and friendly: model chain exhausted → 503 with the draft saved; counter store down → fail open; STT down → a typed error.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-21" disabled="disabled"><label class="task-list-item-label" for="task-item-21"><code>/api/health</code> is the deploy&#39;s readiness probe (503 when no key or no tools).</label></li></ul><h2 id="_5-cost-abuse" tabindex="-1">5. Cost &amp; abuse <a class="header-anchor" href="#_5-cost-abuse" aria-label="Permalink to “5. Cost &amp; abuse”">​</a></h2><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-22" disabled="disabled"><label class="task-list-item-label" for="task-item-22"> Rate limits on session creation, turns per session, turns per IP, uploads, transcriptions; one in-flight turn per session; a global in-flight cap; <code>AGENT_TRUST_PROXY</code> only behind a proxy.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-23" disabled="disabled"><label class="task-list-item-label" for="task-item-23"> Usage caps in plan tokens per user (5h/day/week/month) and per session; context cap; users see a percentage.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-24" disabled="disabled"><label class="task-list-item-label" for="task-item-24"> Tool-output trimming on; the typed prompt on for multi-variant domains; a cheap decision instead of a model call for routing.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-25" disabled="disabled"><label class="task-list-item-label" for="task-item-25"> Model endpoints priced (<code>LLM_&lt;NAME&gt;_PRICE</code>) so the ledger carries vendor cost; metering sink configured if you bill.</label></li></ul><h2 id="_6-observability" tabindex="-1">6. Observability <a class="header-anchor" href="#_6-observability" aria-label="Permalink to “6. Observability”">​</a></h2><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-26" disabled="disabled"><label class="task-list-item-label" for="task-item-26"><code>AGENT_O2_URL</code> (or an OTLP collector) set; traces, metrics and logs arrive; the behaviour panel shows runtime interventions.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-27" disabled="disabled"><label class="task-list-item-label" for="task-item-27"> Alerts: turn error ratio, model unavailable, circuit open, rate-limit bursts, p95 latency, cost per hour.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-28" disabled="disabled"><label class="task-list-item-label" for="task-item-28"><code>npm run check:otel</code> green in CI; the privacy scan finds no user text in labels.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-29" disabled="disabled"><label class="task-list-item-label" for="task-item-29"> Structured logs ship off the main thread; retention set (<code>AGENT_LOG_RETENTION_DAYS</code>, <code>AGENT_SESSION_RETENTION_DAYS</code>).</label></li></ul><h2 id="_7-deploy-hygiene" tabindex="-1">7. Deploy hygiene <a class="header-anchor" href="#_7-deploy-hygiene" aria-label="Permalink to “7. Deploy hygiene”">​</a></h2><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-30" disabled="disabled"><label class="task-list-item-label" for="task-item-30"> Docker runs as a non-root user with a HEALTHCHECK; images build from the repo root.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-31" disabled="disabled"><label class="task-list-item-label" for="task-item-31"> A compose stack with TLS in front (deploy/) and a tested runbook (deploy/DEPLOY.md).</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-32" disabled="disabled"><label class="task-list-item-label" for="task-item-32"><code>.env.production.example</code> documents EVERY variable and stays current.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-33" disabled="disabled"><label class="task-list-item-label" for="task-item-33"> Multi-node: Redis + Mongo configured; sticky sessions recommended (in-flight guards are per node).</label></li></ul><h2 id="_8-data-safety-rails-dev-time" tabindex="-1">8. Data safety rails (dev time) <a class="header-anchor" href="#_8-data-safety-rails-dev-time" aria-label="Permalink to “8. Data safety rails (dev time)”">​</a></h2><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-34" disabled="disabled"><label class="task-list-item-label" for="task-item-34"> All writes gated by <code>AGENT_ALLOW_WRITES=true</code>; the eval gateway runs with writes off; the runner refuses write scenarios otherwise.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-35" disabled="disabled"><label class="task-list-item-label" for="task-item-35"> Probe/seed scripts require <code>--yes</code>, tag their records, clean up, report what they could not clean.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-36" disabled="disabled"><label class="task-list-item-label" for="task-item-36"> Secrets only in <code>.env</code> (gitignored); a committed <code>.env.example</code> with placeholders.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-37" disabled="disabled"><label class="task-list-item-label" for="task-item-37"> PII scrubbed from read-tool results (contact fields) before anything reaches the model.</label></li></ul><hr><p><small>Source: <a href="https://github.com/marg-adk/marg/blob/main/docs/PRODUCTION-CHECKLIST.md">docs/PRODUCTION-CHECKLIST.md</a> — edit it there; the site mirrors the repository.</small></p>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};